CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE member_role AS ENUM ('organization_admin','team_admin','head_coach','assistant_coach','viewer');
CREATE TYPE attendance_status AS ENUM ('present','absent','late','partial','injured','trial');

CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_members (organization_id uuid REFERENCES organizations ON DELETE CASCADE, user_id uuid REFERENCES users ON DELETE CASCADE, role member_role NOT NULL, PRIMARY KEY (organization_id,user_id));
CREATE TABLE teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, name text NOT NULL, game_format text NOT NULL CHECK (game_format IN ('5v5','7v7','9v9','11v11')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE team_members (team_id uuid REFERENCES teams ON DELETE CASCADE, user_id uuid REFERENCES users ON DELETE CASCADE, role member_role NOT NULL, PRIMARY KEY (team_id,user_id));
CREATE TABLE seasons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_id uuid NOT NULL REFERENCES teams ON DELETE CASCADE, name text NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, CHECK (starts_on <= ends_on));
CREATE TABLE players (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_id uuid NOT NULL REFERENCES teams ON DELETE CASCADE, name text NOT NULL, birth_year int NOT NULL, shirt_number int, positions text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE skill_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES organizations ON DELETE CASCADE, name text NOT NULL, sort_order int NOT NULL DEFAULT 0);
CREATE TABLE skills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid NOT NULL REFERENCES skill_categories ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '');
CREATE TABLE player_skill_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), player_id uuid NOT NULL REFERENCES players ON DELETE CASCADE, skill_id uuid NOT NULL REFERENCES skills ON DELETE CASCADE, level smallint NOT NULL CHECK (level BETWEEN 0 AND 5), context text NOT NULL, comment text, assessed_by uuid NOT NULL REFERENCES users, assessed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE development_goals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), player_id uuid NOT NULL REFERENCES players ON DELETE CASCADE, title text NOT NULL, description text NOT NULL DEFAULT '', starts_on date NOT NULL, ends_on date NOT NULL, status text NOT NULL, created_by uuid NOT NULL REFERENCES users, CHECK (starts_on <= ends_on));
CREATE TABLE development_goal_skills (goal_id uuid REFERENCES development_goals ON DELETE CASCADE, skill_id uuid REFERENCES skills ON DELETE CASCADE, desired_level smallint CHECK (desired_level BETWEEN 0 AND 5), PRIMARY KEY(goal_id,skill_id));
CREATE TABLE exercises (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES organizations ON DELETE CASCADE, name text NOT NULL, summary text NOT NULL, instructions text NOT NULL DEFAULT '', min_players int NOT NULL, max_players int NOT NULL, duration_minutes int NOT NULL CHECK(duration_minutes > 0), visibility text NOT NULL DEFAULT 'organization', version int NOT NULL DEFAULT 1, created_by uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(min_players <= max_players));
CREATE TABLE exercise_skills (exercise_id uuid REFERENCES exercises ON DELETE CASCADE, skill_id uuid REFERENCES skills ON DELETE CASCADE, primary_skill boolean NOT NULL DEFAULT false, PRIMARY KEY(exercise_id,skill_id));
CREATE TABLE exercise_diagrams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exercise_id uuid NOT NULL REFERENCES exercises ON DELETE CASCADE, version int NOT NULL DEFAULT 1, width_ratio numeric NOT NULL DEFAULT .65, objects jsonb NOT NULL DEFAULT '[]', actions jsonb NOT NULL DEFAULT '[]', CHECK(jsonb_typeof(objects)='array'), CHECK(jsonb_typeof(actions)='array'));
CREATE TABLE training_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_id uuid NOT NULL REFERENCES teams ON DELETE CASCADE, season_id uuid REFERENCES seasons ON DELETE SET NULL, title text NOT NULL, theme text NOT NULL, starts_at timestamptz NOT NULL, planned_minutes int NOT NULL CHECK(planned_minutes > 0), status text NOT NULL DEFAULT 'draft', created_by uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE training_session_blocks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES training_sessions ON DELETE CASCADE, exercise_id uuid REFERENCES exercises ON DELETE SET NULL, title text NOT NULL, minutes int NOT NULL CHECK(minutes > 0), sort_order int NOT NULL, coaching_points text[] NOT NULL DEFAULT '{}');
CREATE TABLE training_session_attendance (session_id uuid REFERENCES training_sessions ON DELETE CASCADE, player_id uuid REFERENCES players ON DELETE CASCADE, status attendance_status NOT NULL, minutes int, recorded_by uuid REFERENCES users, PRIMARY KEY(session_id,player_id));
CREATE TABLE season_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), season_id uuid NOT NULL REFERENCES seasons ON DELETE CASCADE, name text NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, theme text NOT NULL, notes text NOT NULL DEFAULT '', CHECK(starts_on <= ends_on));
CREATE TABLE season_period_skills (period_id uuid REFERENCES season_periods ON DELETE CASCADE, skill_id uuid REFERENCES skills ON DELETE CASCADE, PRIMARY KEY(period_id,skill_id));
CREATE TABLE matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_id uuid NOT NULL REFERENCES teams ON DELETE CASCADE, opponent text NOT NULL, starts_at timestamptz NOT NULL, location text, game_format text NOT NULL, result text);
CREATE TABLE match_observations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), match_id uuid NOT NULL REFERENCES matches ON DELETE CASCADE, summary text NOT NULL, sentiment text NOT NULL CHECK(sentiment IN ('positive','develop','neutral')), priority boolean NOT NULL DEFAULT false, player_id uuid REFERENCES players ON DELETE SET NULL, created_by uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE match_observation_skills (observation_id uuid REFERENCES match_observations ON DELETE CASCADE, skill_id uuid REFERENCES skills ON DELETE CASCADE, PRIMARY KEY(observation_id,skill_id));
CREATE TABLE activity_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, actor_id uuid REFERENCES users, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, created_at timestamptz NOT NULL DEFAULT now());

CREATE INDEX players_team_idx ON players(team_id);
CREATE INDEX sessions_team_start_idx ON training_sessions(team_id,starts_at);
CREATE INDEX observations_match_idx ON match_observations(match_id);
